  FT["PH-H2159"] = {"id":"PH-H2159","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2427_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Tarlac市","en":"An Act Converting the Tarlac Trade School in the Municipality of Tarlac, Province of Tarlac, into a Regional National School of Arts and Trades to be Known as the Tarlac School of Arts and Trades, and Authorizing the Appropriation of the Necessary Funds Therefor","orig":"An Act Converting the Tarlac Trade School in the Municipality of Tarlac, Province of Tarlac, into a Regional National School of Arts and Trades to be Known as the Tarlac School of Arts and Trades, and Authorizing the Appropriation of the Necessary Funds Therefor"},"level":"law","status":"active","topics":["trade","education","culture"],"docNumber":"Republic Act No. 2427","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2427_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2159-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Tarlac Trade School in the Municipality of Tarlac, Province of Tarlac, is hereby converted into a regional national school of arts and trades of the Philippine School of Arts and Trades type to be known as the Tarlac School of Arts and Trades. The said school shall be under the supervision of the Bureau of Public Schools and subject to the provisions of the school law. Courses of collegiate and secondary levels shall be offered in the said school."}},{"id":"PH-H2159-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of said school during the fiscal year nineteen hundred sixty. Such sum as may be necessary for its operation and maintenance in subsequent years shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2159-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon the date the funds authorized herein to be appropriated shall have been provided for.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2160"] = {"id":"PH-H2160","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2428_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Convert the San Fernando High School in the Municipality of San Fernando, Province of Romblon, into a National Vocational High School to be Known as the Romblon National Vocational School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Convert the San Fernando High School in the Municipality of San Fernando, Province of Romblon, into a National Vocational High School to be Known as the Romblon National Vocational School, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2428","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2428_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2160-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The San Fernando High School in the Municipality of Sand Fernando, Province of Romblon, is hereby converted into a national vocational high school to be known as the Romblon National Vocational School. The Director of Public Schools, subject to the approval of the Secretary of Education, is hereby empowered to reorganize said school accordingly."}},{"id":"PH-H2160-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the expenses of the said school during the fiscal year ending June thirty, nineteen hundred and sixty, including the purchase of a suitable school site. In the succeeding years the operating expenses thereof shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2160-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon the date the funds authorized herein to be appropriated shall have been provided for.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2161"] = {"id":"PH-H2161","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2429_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Establishing a Marine Fisheries Laboratory at Guiuan, Samar, Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a Marine Fisheries Laboratory at Guiuan, Samar, Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 2429","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2429_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2161-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established and maintained under the supervision of the Director of Fisheries a marine fisheries laboratory in the Municipality of Guiuan, Province of Samar."}},{"id":"PH-H2161-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of three hundred fifty thousand pesos is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, to carry into effect the purposes of this Act during the fiscal year ending June thirtieth, nineteen hundred and fifty-nine. Thereafter, the necessary amount for the purpose shall be included in the General Appropriation Act of each year."}},{"id":"PH-H2161-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2162"] = {"id":"PH-H2162","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2430_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Maintain a National Agricultural High School in the Municipality of Sta. Maria, Province of Pangasinan, to be Known as Eastern Pangasinan Agricultural High School, and to Authorize the Appropriation of Funds Therefor","orig":"An Act to Maintain a National Agricultural High School in the Municipality of Sta. Maria, Province of Pangasinan, to be Known as Eastern Pangasinan Agricultural High School, and to Authorize the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 2430","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2430_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2162-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Bureau of Public Schools shall maintain a national agricultural school of secondary level to be known as Eastern Pangasinan Agricultural High School in the Municipality of Sta. Maria, Province of Pangasinan."}},{"id":"PH-H2162-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Director of Public Schools is authorized to locate and acquire a suitable site for the school, which may be public or private lands situated in the said Municipality of Sta. Maria."}},{"id":"PH-H2162-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of the school during the first year of its operation, including the acquisition of the site of the school."}},{"id":"PH-H2162-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon the date the funds authorized herein to be appropriated shall have been provided for.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2163"] = {"id":"PH-H2163","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2431_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Convert the Mampising National Agricultural High School in the Municipality of Mabini, Province of Davao, into a National Regional Agricultural School of the Camarines Sur National Regional Agricultural School Type, to be Known as the Davao National Regional Agricultural School, Authorizing the Appropriation of Funds Therefor","orig":"An Act to Convert the Mampising National Agricultural High School in the Municipality of Mabini, Province of Davao, into a National Regional Agricultural School of the Camarines Sur National Regional Agricultural School Type, to be Known as the Davao National Regional Agricultural School, Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 2431","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2431_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2163-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Mampising National Agricultural High School in the Municipality of Mabini, Province of Davao, is hereby converted into a national regional agricultural school of the Camarines Sur National Regional Agricultural School type, to be known as the Davao National Regional Agricultural School. The supervision and administration of the existing Davao National Agricultural School located in the Municipality of Saug, Province of Davao, which shall be a branch of the Davao National Regional Agricultural School, shall be under the superintendent of the latter school."}},{"id":"PH-H2163-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Director of Public Schools, subject to the approval of the Secretary of Education, is hereby authorized to reorganize the existing Mampising National Agricultural High School and the Davao National Agricultural School to implement the provision of section one above."}},{"id":"PH-H2163-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred fifty thousand pesos, in addition to the national allotments now being received by the Mampising National Agricultural High School and the Davao National Agricultural School, is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of said school including the Davao National Agricultural School for the fiscal year nineteen hundred sixty. Thereafter, the necessary sum for the said purpose shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2163-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon the date the funds authorized herein to be appropriated shall have been provided for.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2164"] = {"id":"PH-H2164","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2432_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Kiangan市","en":"An Act Converting the Nayon Primary School in the Municipality of Kiangan, Mountain Province, into a Pilot Opportunity School of Agriculture, and Authorizing the Appropriation of the Necessary Funds Therefor","orig":"An Act Converting the Nayon Primary School in the Municipality of Kiangan, Mountain Province, into a Pilot Opportunity School of Agriculture, and Authorizing the Appropriation of the Necessary Funds Therefor"},"level":"law","status":"active","topics":["education","environment","culture"],"docNumber":"Republic Act No. 2432","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2432_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2164-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Nayon Primary School in the Municipality of Kiangan, Mountain Province, is hereby converted into a pilot opportunity school of agriculture to be known as the Ifugao Pilot Opportunity School of Agriculture. It shall teach practical scientific farming to youth and adult alike. The Secretary of Education is hereby empowered to organize the said school accordingly.\nUpon the organization of the said school, the assets, liabilities, personnel, equipment and records of the Nayon Primary School shall be transferred to the former."}},{"id":"PH-H2164-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of the said school for the year nineteen hundred fifty-nine to nineteen hundred sixty, thereafter, the necessary sum for the operation thereof shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2164-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon the date the funds authorized herein to be appropriated shall have been provided for.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2165"] = {"id":"PH-H2165","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2433_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Convert the Balangiga Junior High School in the Municipality of Balangiga, Province of Samar, into a Rural High School to be Known as the Balangiga Rural High School","orig":"An Act to Convert the Balangiga Junior High School in the Municipality of Balangiga, Province of Samar, into a Rural High School to be Known as the Balangiga Rural High School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2433","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2433_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2165-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Balangiga Junior High School in the Municipality of Balangiga, Province of Samar, is hereby converted into a rural high school to be known as the Balangiga Rural High School, The Director of Public Schools, subject to the approval of the Secretary of Education, is hereby empowered to reorganize said school accordingly."}},{"id":"PH-H2165-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred fifty thousand pesos, in addition to what the school is now receiving, is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of the said school during the school year nineteen hundred and fifty-nine to nineteen hundred and sixty. Thereafter, the amount shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2165-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon the date the funds authorized herein to be appropriated shall have been provided for.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2166"] = {"id":"PH-H2166","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2434_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Establish a National Regional Agricultural School in the Municipality of Borongan, Province of Samar, to be Known as the Eastern Samar, National Regional Agricultural School","orig":"An Act to Establish a National Regional Agricultural School in the Municipality of Borongan, Province of Samar, to be Known as the Eastern Samar, National Regional Agricultural School"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 2434","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2434_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2166-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Public Schools, a national regional agricultural school of the Negros Occidental National Agricultural School type in the Municipality of Borongan, Province of Samar, at a suitable site to be selected by said Director, to be known as the Eastern Samar National Regional Agricultural School."}},{"id":"PH-H2166-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon the recommendation of the Director of Public Schools, the President shall set aside and reserve such portion of the public lands located within the Municipality of Borongan of said province, as may be necessary and convenient for the establishment of the said school and its farm site."}},{"id":"PH-H2166-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of three hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said school during the fiscal year ending June thirty, nineteen hundred sixty. Such sums as may be necessary for its operation and maintenance in subsequent years shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2166-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Thi s Act shall take effect upon the date the funds authorized herein to be appropriated shall have been provided for.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2167"] = {"id":"PH-H2167","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2435_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Convert the Samar Provincial Trade School into a National School of Arts and Trades and to Authorize the Appropriation of Funds Therefor","orig":"An Act to Convert the Samar Provincial Trade School into a National School of Arts and Trades and to Authorize the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["trade","education","culture"],"docNumber":"Republic Act No. 2435","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2435_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2167-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Samar Provincial Trade School in the Municipality of Catbalogan, Province of Samar, is hereby converted into a national school of arts and trades to be known as the Samar National School of Arts and Trades. The Secretary of Education is hereby empowered to reorganize said school accordingly."}},{"id":"PH-H2167-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the provisions of this Act during the fiscal year nineteen hundred sixty. Thereafter, such sums as may be necessary for the same purpose shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2167-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2168"] = {"id":"PH-H2168","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2436_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Maintenance and Operation of a National Vocational High School in the Municipality of Dapitan, Province of Zamboanga del Norte to be Known as the Rizal Memorial National Vocational High School and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Maintenance and Operation of a National Vocational High School in the Municipality of Dapitan, Province of Zamboanga del Norte to be Known as the Rizal Memorial National Vocational High School and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2436","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2436_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2168-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be, under the direct supervision of the Director of Public Schools, a national vocational school in the Municipality of Dapitan Province of Zamboanga del Norte, to be known as the Rizal Memorial National Vocational High School."}},{"id":"PH-H2168-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of the said school for the fiscal year nineteen hundred sixty. Thereafter, the necessary appropriation for its operation shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2168-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon the date the funds authorized herein to be appropriated shall have been provided for.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2169"] = {"id":"PH-H2169","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2437_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Converting the Gonzaga High School in the Province of Cagayan into a National Rural High School of the Alcala Rural High School Type to be Known as the Gonzaga National Rural High School and Authorizing the Appropriation of the Sum of Seventy-Five Thousand Pesos for the Purpose","orig":"An Act Converting the Gonzaga High School in the Province of Cagayan into a National Rural High School of the Alcala Rural High School Type to be Known as the Gonzaga National Rural High School and Authorizing the Appropriation of the Sum of Seventy-Five Thousand Pesos for the Purpose"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2437","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2437_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2169-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Gonzaga High School in the Municipality of Gonzaga, Province of Cagayan, is hereby converted into a national rural high school of the Alcala Rural High School type to be known as the Gonzaga National Rural High School. The Secretary of Education is hereby empowered to reorganize the said school accordingly.\nUpon the organization of the Gonzaga National Rural High School, the assets, liabilities, equipment and record of the Gonzaga High School shall be transferred to the Gonzaga National Rural High School ."}},{"id":"PH-H2169-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of seventy-five thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of the Gonzaga National Rural High School for the first year nineteen hundred fifty-nine to nineteen hundred sixty. Thereafter, the necessary sum for the operation of the said school shall be included in the annual General Appropriation Act."}},{"id":"PH-H2169-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon the date the funds authorized herein to be appropriated shall have been provided for.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2170"] = {"id":"PH-H2170","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2438_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Sections One and Two of Republic Act Numbered Nineteen Hundred Sixty-Five Relative to the Site of the Bataan Agricultural High School","orig":"An Act Amending Sections One and Two of Republic Act Numbered Nineteen Hundred Sixty-Five Relative to the Site of the Bataan Agricultural High School"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 2438","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2438_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2170-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections one and two of Republic Act Numbered Nineteen hundred sixty-five are hereby amended to read as follows:\nSec. 1 . There shall be established, under the direct supervision of the Director of Public Schools, an agricultural high school in the Municipality of Dinalupihan, Province of Bataan, at a suitable site to be selected by said Director, to be known as the Bataan Agricultural High School.\nSec. 2 . Upon the recommendation of the Director of Public Schools, the President shall set aside and reserve such portion of the public lands located within the Municipality of Dinalupihan of said province, as may be necessary and convenient for the establishment of the said school and of its farm site.\""}},{"id":"PH-H2170-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2171"] = {"id":"PH-H2171","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2439_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Tondo Foreshore Land Act of 1956","orig":"An Act to Amend the First Paragraph of Section Two of the “Tondo Foreshore Land Act of 1956”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2439","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2439_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2171-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of section two of Republic Act Numbered Fifteen hundred and ninety-seven, otherwise known as the \"Tondo Foreshore Land Act of 1956,\" is amended to read as follows:\nSec. 2 . Notwithstanding the provisions of the Public Land Act, as amended, and Proclamation Numbered One hundred eighty-seven of the President of the Philippines, dated June seventeen, nineteen hundred fifty, the Director of Lands, under the direction of the Secretary of Agriculture and Natural Resources, is hereby authorized and directed to survey and subdivide immediately the lands in the district of Tondo, City of Manila, comprising what is known as the \"Tondo Foreshore Land,\" which is bounded on the North by the Philippine Manufacturing Company compound up to Vitas (Government Tenement Houses); on the East by privately-owned parcels of land from the present Azcarraga Street extension to the Philippine Manufacturing Company compound at Bangkusay Street extending to Vitas (Government Tenement Houses); and the South by the present Azcarraga Street extension; and on the West by that portion of land one hundred meters from the pier line to the East, with the exception of such areas as are reserved by the Government for port facilities, roads and other public uses, into lots in such a manner that every lessee of any lot in said land or bona fide occupant of any parcel thereof will not be deprived of any part of the same, should he decide to buy it under this Act. The Director of Lands is hereby further directed to complete such survey and subdivision within one year from the date of the approval of this Act, after which said Director shall turn over all the pertinent records or papers of said survey and subdivision to the Land Tenure Administration which is hereby authorized and directed to sell without delay and without the necessity of public bidding the lots as subdivided to their respective lessees and bona fide occupants if they are duly qualified to acquire public lands at the time of the approval of Republic Act Numbered Five hundred fifty-nine, or, in the case of vacant lots, to persons, who are not disqualified to acquire public lands: Provided, That those lessees and bona fide occupants who will be deprived of their lots or parcels of land by reason of the opening or widening of streets and alleys by virtue of the subdivision herein provided, shall be given preference, in the order mentioned, in the award or sale of the vacant lots: Provided, further, That if said vacant lots are not enough to accommodate all such lessees and occupants, the award or sale thereof shall be by lot: Provided, further, That if there are lessees or bona fide occupants who, after going through the above procedures, still are unaccommodated, the same shall be given preference to acquire lots on the reclaimed area towards the East of Bangkusay Street, in the district of Tondo, City of Manila, and/or occupy of buy houses in the housing projects of the People’s Homesite and Housing Corporation to be established in the district of Tondo, City of Manila.\""}},{"id":"PH-H2171-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2172"] = {"id":"PH-H2172","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2440_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Establish a National Trade School in the Municipality of Laoang, Province of Samar","orig":"An Act to Establish a National Trade School in the Municipality of Laoang, Province of Samar"},"level":"law","status":"active","topics":["trade","education"],"docNumber":"Republic Act No. 2440","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2440_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2172-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"A national trade school of the Philippine School of Arts and Trades type, to be known as the Laoang National Trade School, shall be established in the Municipality of Laoang, Province of Samar. The said school shall be under the supervision of the Bureau of Public Schools and subject to the provisions of the School Law. Courses of secondary level shall be offered in the said school."}},{"id":"PH-H2172-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said school for the fiscal year ending June thirty nineteen hundred sixty. Such sum as may be necessary for its operation and maintenance in subsequent years shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2172-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2173"] = {"id":"PH-H2173","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2441_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of a National Vocational School in Calbayog City to be Known as the Tiburcio Tancinco Memorial Vocational School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a National Vocational School in Calbayog City to be Known as the Tiburcio Tancinco Memorial Vocational School, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2441","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2441_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2173-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Public Schools, a national vocations school to be known as the Tiburcio Tancinco Memorial Vocational School. Courses of secondary level shall be offered in the said school."}},{"id":"PH-H2173-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Director of Public Schools shall, with the approval of the Secretary of Education, issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H2173-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, but of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said school during the fiscal year nineteen hundred sixty. Such sums as may be needed for the same purpose in subsequent years shall be included in the annual General Appropriations Acts."}},{"id":"PH-H2173-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Acts shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2174"] = {"id":"PH-H2174","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2443_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Increase the Bed Capacity of the Eastern Pangasinan General Hospital and Authorizing the Appropriation of Funds for the Purpose","orig":"An Act to Increase the Bed Capacity of the Eastern Pangasinan General Hospital and Authorizing the Appropriation of Funds for the Purpose"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 2443","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2443_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2174-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Eastern Pangasinan General Hospital is hereby increased from twenty-five to fifty."}},{"id":"PH-H2174-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount of fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of the hospital in addition to its existing funds."}},{"id":"PH-H2174-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2175"] = {"id":"PH-H2175","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2444_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Item 81, for the Province of Laguna, Page 162, Paragraph g, Section Two of Republic Act Numbered Sixteen Hundred Thirteen","orig":"An Act Amending Item 81, for the Province of Laguna, Page 162, Paragraph g, Section Two of Republic Act Numbered Sixteen Hundred Thirteen"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2444","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2444_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2175-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item 81, for the Province of Laguna, page 162, paragraph g, section two of Republic Act Numbered Sixteen hundred thirteen is amended to read as follows:\n\"81. Santa Cruz Town Hall, Sta. Cruz ₱10,000.00.\""}},{"id":"PH-H2175-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2176"] = {"id":"PH-H2176","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2445_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"对第 1- 条的修改","en":"An Act to Amend Item (17), Page 4, Section 1-A-a, Title (A) of Republic Act Numbered Nineteen Hundred","orig":"An Act to Amend Item (17), Page 4, Section 1-A-a, Title (A) of Republic Act Numbered Nineteen Hundred"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2445","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2445_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2176-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item (17), page 4, section 1-A-a, Title (A) of Republic Act Numbered Nineteen hundred is amended to read as follows:\n\"(17) Industrial Arts Annex, Iloilo Vocational High School-Lambunao ₱20,000.00\""}},{"id":"PH-H2176-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2177"] = {"id":"PH-H2177","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2446_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend Certain Items in Section One, Republic Act Numbered Two Thousand Ninety-Three","orig":"An Act to Amend Certain Items in Section One, Republic Act Numbered Two Thousand Ninety-Three"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2446","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2446_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2177-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Items (m) and (n), for the Province of Leyte, sub-paragraph twenty-three, paragraph a, Title D, section one of Republic Act Numbered Two thousand ninety-three, is hereby amended to read as follows:\n\"(m) San Roque Waterworks, Macrohon ₱5,000.00 \"(n) San Isidro Waterworks, Malitbog 20,000.00\""}},{"id":"PH-H2177-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2178"] = {"id":"PH-H2178","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2447_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Operation and Maintenance of a Public Emergency Hospital in the Municipality of Diffun, Province of Nueva Vizcaya, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Operation and Maintenance of a Public Emergency Hospital in the Municipality of Diffun, Province of Nueva Vizcaya, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 2447","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2447_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2178-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established in the Municipality of Diffun, Province of Nueva Vizcaya, a public hospital to be known as the Northeastern Nueva Vizcaya Emergency Hospital. The site of said hospital shall be determined by a board composed of five members, namely, the Director of Medical Services or his duly authorized representative who shall act as chairman, the municipal mayor, the district engineer, and two members of the municipal council of said municipality to be designated by the municipal mayor."}},{"id":"PH-H2178-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of seventy-five thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty. Such sums as may be necessary for its operation and maintenance in subsequent years shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2178-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon the date the funds authorized herein to be appropriated are provided for.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2179"] = {"id":"PH-H2179","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2449_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of a Hospital in the Municipality of Guiuan, Province of Samar, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a Hospital in the Municipality of Guiuan, Province of Samar, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 2449","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2449_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2179-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Medical Services, a hospital in the Municipality of Guiuan, Province of Samar, to be known as the Guiuan Emergency Hospital."}},{"id":"PH-H2179-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H2179-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty. Such sums as may be needed for the same purpose in subsequent years shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2179-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2180"] = {"id":"PH-H2180","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2450_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Repeal Republic Act Numbered Fourteen Hundred Seventy, Entitled “An Act to Amend and Repeal Certain Items in Republic Act Numbered Fourteen Hundred Eleven, Regarding Public Works Projects for the Province of Bohol","orig":"An Act to Repeal Republic Act Numbered Fourteen Hundred Seventy, Entitled “An Act to Amend and Repeal Certain Items in Republic Act Numbered Fourteen Hundred Eleven, Regarding Public Works Projects for the Province of Bohol"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2450","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2450_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2180-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Republic Act Numbered Fourteen hundred seventy is hereby repealed."}},{"id":"PH-H2180-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The items in Republic Act Numbered Fourteen hundred eleven which were amended or repealed by Republic Act Numbered Fourteen hundred seventy are hereby reenacted and revived."}},{"id":"PH-H2180-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2181"] = {"id":"PH-H2181","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2451_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of an Emergency Hospital in the Island of Ticao, Province of Masbate, to be Known as the Ticao Emergency Hospital, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of an Emergency Hospital in the Island of Ticao, Province of Masbate, to be Known as the Ticao Emergency Hospital, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 2451","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2451_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2181-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be created and established, under the direct supervision of the Bureau of Medical Services, an emergency hospital in the Island of Ticao, Province of Masbate, to be known as the Ticao Emergency Hospital. The site for the said hospital shall be the Municipality of San Jacinto to be provided by the Municipal Council of said municipality in consultation with the Director of the Bureau of Medical Services."}},{"id":"PH-H2181-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall promulgate such rules and regulations as may be necessary to carry into effect the purposes of this Act."}},{"id":"PH-H2181-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment and operation of the said hospital during the fiscal year ending June thirty, nineteen hundred sixty. Such sums as may be necessary for its operation and maintenance in subsequent years shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2181-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon the date the funds authorized herein to be appropriated are provided for.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2182"] = {"id":"PH-H2182","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2452_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Municipal Districts in the Province of Quezon","orig":"An Act Creating Municipal Districts in the Province of Quezon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2452","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2452_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2182-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Mangetahan, Dimasisit, Dilasag and Esperanza are separated from the Municipality of Casiguran, Province of Quezon, and are constituted into a distinct and independent municipal district to be known as the Municipal District of Dilasag."}},{"id":"PH-H2182-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The barrios of San Luis, Bacong and Ditumabo are hereby separated from the Municipality of Baler, same province, and are constituted into a distinct and independent municipal district to be known as the Municipal District of San Luis."}},{"id":"PH-H2182-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The barrios of Panukulan, Calasumanga, Libo, and Lipata are hereby separated from the Municipality of Polillo, same province, and are constituted into a distinct and independent municipal district to be known as the Municipal District of Panukulan."}},{"id":"PH-H2182-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
  FT["PH-H2183"] = {"id":"PH-H2183","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2453_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Certain Items of Republic Act Numbered Twenty Hundred and Ninety-Three","orig":"An Act Amending Certain Items of Republic Act Numbered Twenty Hundred and Ninety-Three"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2453","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2453_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2183-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item III (f), for the Province of Cebu, page two hundred five of Republic Act Numbered Twenty hundred and ninety-three, is hereby amended to read as follows:\nIII \"(f) Ocaña Elementary School, Carcar Construction of one additional room ₱6,000.00 \"(f) Standard shop building, Noel-type, size: 6.90 X 8.55, Carcar Construction ₱6,000.00\""}},{"id":"PH-H2183-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p30"};
